export function pythonTypeName(value) {
  if (value === null) {
    return 'NoneType';
  }

  if (Array.isArray(value)) {
    return 'list';
  }

  switch (typeof value) {
    case 'string':
      return 'str';
    case 'boolean':
      return 'bool';
    case 'number':
      return Number.isInteger(value) ? 'int' : 'float';
    case 'object':
